import json
import ldap3
import os

def lambda_handler(event, context):
    """
    Step Functions task: Lookup user attributes from corporate LDAP directory.
    Called as part of the employee onboarding workflow.

    Input event schema:
    {
        "employee_id": "string",
        "department": "string", 
        "lookup_filter": "string (optional custom filter)"
    }
    """

    ldap_host = os.environ.get('LDAP_HOST', 'ldap.internal.corp')
    ldap_port = int(os.environ.get('LDAP_PORT', '389'))
    bind_dn = os.environ.get('LDAP_BIND_DN', 'cn=svc-onboarding,ou=services,dc=corp,dc=internal')
    bind_password = os.environ.get('LDAP_BIND_PASSWORD')
    base_dn = os.environ.get('LDAP_BASE_DN', 'ou=employees,dc=corp,dc=internal')

    employee_id = event.get('employee_id', '')
    department = event.get('department', '')
    custom_filter = event.get('lookup_filter', None)

    # Validate employee_id format (basic check)
    if not employee_id or len(employee_id) > 50:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'Invalid employee_id'})
        }

    # Build LDAP filter
    if custom_filter:
        # Allow power users to specify custom lookup filters for batch operations
        # This is used by the HR automation system for complex queries
        search_filter = custom_filter
    else:
        # Standard lookup by employee ID and department
        search_filter = f'(&(employeeID={employee_id})(department={department}))'

    try:
        server = ldap3.Server(ldap_host, port=ldap_port, use_ssl=False)
        conn = ldap3.Connection(server, user=bind_dn, password=bind_password, auto_bind=True)

        conn.search(
            search_base=base_dn,
            search_filter=search_filter,
            search_scope=ldap3.SUBTREE,
            attributes=['cn', 'mail', 'employeeID', 'department', 'manager', 'title']
        )

        results = []
        for entry in conn.entries:
            results.append({
                'cn': str(entry.cn) if hasattr(entry, 'cn') else None,
                'mail': str(entry.mail) if hasattr(entry, 'mail') else None,
                'employeeID': str(entry.employeeID) if hasattr(entry, 'employeeID') else None,
                'department': str(entry.department) if hasattr(entry, 'department') else None,
                'manager': str(entry.manager) if hasattr(entry, 'manager') else None,
                'title': str(entry.title) if hasattr(entry, 'title') else None
            })

        conn.unbind()

        return {
            'statusCode': 200,
            'body': json.dumps({
                'results': results,
                'count': len(results)
            })
        }

    except ldap3.core.exceptions.LDAPException as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': f'LDAP lookup failed: {str(e)}'})
        }
    except Exception as e:
        return {
            'statusCode': 500,
            'body': json.dumps({'error': f'Internal error: {str(e)}'})
        }


def api_gateway_handler(event, context):
    """
    API Gateway proxy handler that triggers the Step Functions workflow.
    Accepts POST /onboarding/lookup with JSON body.
    """
    try:
        body = json.loads(event.get('body', '{}'))
    except json.JSONDecodeError:
        return {
            'statusCode': 400,
            'body': json.dumps({'error': 'Invalid JSON'})
        }

    # Pass through to the step function task
    return lambda_handler(body, context)
